 filters=''.join(f'<button type="button" data-filter="{key}" aria-pressed="{str(i==0).lower()}">{label}</button>' for i,(key,label) in enumerate(zip(['all','data','ml','software','research'],c['filters'])))
 expertise=''.join(f'<article><span class="micro">0{i+1}</span><h3>{title}</h3><p>{desc}</p><div class="tech">{stack}</div></article>' for i,(title,stack,desc) in enumerate(c['experts']))
 experience=''.join(f'<article class="experience-row"><time>{date}</time><div><h4>{company}</h4><h3>{role}</h3><p>{desc}</p></div></article>' for date,company,role,desc in c['exp'])
